 {
 	struct net_device *dev = skb_dst_dev(skb);
 	struct timespec64 ts;
 	ktime_t tstamp;
 	u64 raw64;
 	u32 raw32;
 	u16 raw16;
 	u8 *data;
 	u8 byte;

 	data = trace->data + trace->remlen * 4 - trace->nodelen * 4 - sclen * 4;

 	/* hop_lim and node_id */
 	if (trace->type.bit0) {
 		byte = ipv6_hdr(skb)->hop_limit;
 		if (is_input)
 			byte--;

 		raw32 = dev_net(dev)->ipv6.sysctl.ioam6_id;

 		*(__be32 *)data = cpu_to_be32((byte << 24) | raw32);
 		data += sizeof(__be32);
 	}

 	/* ingress_if_id and egress_if_id */
 	if (trace->type.bit1) {
 		if (!skb->dev)
 			raw16 = IOAM6_U16_UNAVAILABLE;
 		else
 			raw16 = (__force u16)READ_ONCE(__in6_dev_get(skb->dev)->cnf.ioam6_id);

 		*(__be16 *)data = cpu_to_be16(raw16);
 		data += sizeof(__be16);

 		if (dev->flags & IFF_LOOPBACK)
 			raw16 = IOAM6_U16_UNAVAILABLE;
 		else
 			raw16 = (__force u16)READ_ONCE(__in6_dev_get(dev)->cnf.ioam6_id);

 		*(__be16 *)data = cpu_to_be16(raw16);
 		data += sizeof(__be16);
 	}

 	/* timestamp seconds */
 	if (trace->type.bit2) {
 		if (!skb->dev) {
 			*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		} else {
 			tstamp = skb_tstamp_cond(skb, true);
 			ts = ktime_to_timespec64(tstamp);

 			*(__be32 *)data = cpu_to_be32((u32)ts.tv_sec);
 		}
 		data += sizeof(__be32);
 	}

 	/* timestamp subseconds */
 	if (trace->type.bit3) {
 		if (!skb->dev) {
 			*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		} else {
 			if (!trace->type.bit2) {
 				tstamp = skb_tstamp_cond(skb, true);
 				ts = ktime_to_timespec64(tstamp);
 			}

 			*(__be32 *)data = cpu_to_be32((u32)(ts.tv_nsec / NSEC_PER_USEC));
 		}
 		data += sizeof(__be32);
 	}

 	/* transit delay */
 	if (trace->type.bit4) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* namespace data */
 	if (trace->type.bit5) {
 		*(__be32 *)data = ns->data;
 		data += sizeof(__be32);
 	}

 	/* queue depth */
 	if (trace->type.bit6) {
 		struct netdev_queue *queue;
 		struct Qdisc *qdisc;
 		__u32 qlen, backlog;

 		if (dev->flags & IFF_LOOPBACK) {
 			*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		} else {
 			queue = skb_get_tx_queue(dev, skb);
 			qdisc = rcu_dereference(queue->qdisc);
 			qdisc_qstats_qlen_backlog(qdisc, &qlen, &backlog);

 			*(__be32 *)data = cpu_to_be32(backlog);
 		}
 		data += sizeof(__be32);
 	}

 	/* checksum complement */
 	if (trace->type.bit7) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* hop_lim and node_id (wide) */
 	if (trace->type.bit8) {
 		byte = ipv6_hdr(skb)->hop_limit;
 		if (is_input)
 			byte--;

 		raw64 = dev_net(dev)->ipv6.sysctl.ioam6_id_wide;

 		*(__be64 *)data = cpu_to_be64(((u64)byte << 56) | raw64);
 		data += sizeof(__be64);
 	}

 	/* ingress_if_id and egress_if_id (wide) */
 	if (trace->type.bit9) {
 		if (!skb->dev)
 			raw32 = IOAM6_U32_UNAVAILABLE;
 		else
 			raw32 = READ_ONCE(__in6_dev_get(skb->dev)->cnf.ioam6_id_wide);

 		*(__be32 *)data = cpu_to_be32(raw32);
 		data += sizeof(__be32);

 		if (dev->flags & IFF_LOOPBACK)
 			raw32 = IOAM6_U32_UNAVAILABLE;
 		else
 			raw32 = READ_ONCE(__in6_dev_get(dev)->cnf.ioam6_id_wide);

 		*(__be32 *)data = cpu_to_be32(raw32);
 		data += sizeof(__be32);
 	}

 	/* namespace data (wide) */
 	if (trace->type.bit10) {
 		*(__be64 *)data = ns->data_wide;
 		data += sizeof(__be64);
 	}

 	/* buffer occupancy */
 	if (trace->type.bit11) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* bit12 undefined: filled with empty value */
 	if (trace->type.bit12) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* bit13 undefined: filled with empty value */
 	if (trace->type.bit13) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* bit14 undefined: filled with empty value */
 	if (trace->type.bit14) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* bit15 undefined: filled with empty value */
 	if (trace->type.bit15) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* bit16 undefined: filled with empty value */
 	if (trace->type.bit16) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* bit17 undefined: filled with empty value */
 	if (trace->type.bit17) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* bit18 undefined: filled with empty value */
 	if (trace->type.bit18) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* bit19 undefined: filled with empty value */
 	if (trace->type.bit19) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* bit20 undefined: filled with empty value */
 	if (trace->type.bit20) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* bit21 undefined: filled with empty value */
 	if (trace->type.bit21) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* opaque state snapshot */
 	if (trace->type.bit22) {
 		if (!sc) {
 			*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE >> 8);
 		} else {
 			*(__be32 *)data = sc->hdr;
 			data += sizeof(__be32);

 			memcpy(data, sc->data, sc->len);
 		}
 	}
